import React, { useEffect, useState } from 'react';
import axios            from 'axios';
import { useParams,useNavigate } from 'react-router-dom';

export default function EditDriverForm() {
  const { id } = useParams<{id:string}>();
  const [f, setF] = useState({ name:'', email:'', phone:'', address:'', licenseNumber:'' });
  const nav = useNavigate();

  useEffect(()=>{
    axios.get(`${process.env.REACT_APP_API_URL}/api/drivers/${id}`)
         .then(r=>setF(r.data));
  },[id]);

  const sub = async (e:any)=> {
    e.preventDefault();
    await axios.put(`${process.env.REACT_APP_API_URL}/api/drivers/${id}`, f);
    nav('/drivers');
  };

  return (
    <form onSubmit={sub} style={{padding:20,maxWidth:400,margin:'auto'}}>
      <h3>Edit Driver</h3>
      {(['name','email','phone','address','licenseNumber'] as const).map(k=>(
        <input
          key={k} value={(f as any)[k]}
          onChange={e=>setF({...f,[k]:e.target.value})}
          placeholder={k}
        />
      ))}
      <button type="submit">Save</button>
    </form>
  );
}
